{
  "command": "replace_content_by_matching",
  "args": {
    "old_content": "    // Present state register (driven from input y each cycle)
    // The spec's table defines transitions based on present y[2:0].
    logic [2:0] state;
    logic [2:0] next_state;

    initial begin
        state = 3'b000;
    end

    // State update: treat input y as the present-state encoding for this FSM
    // (so the FSM's 'present state input y' is sampled into internal state).
    always @(posedge clk) begin
        state <= y;
    end

    // Next-state combinational logic from the table.
    always @(*) begin
        next_state = 3'b000;
        case (state)
            3'b000: next_state = (x) ? 3'b001 : 3'b000;
            3'b001: next_state = (x) ? 3'b100 : 3'b001;
            3'b010: next_state = (x) ? 3'b001 : 3'b010;
            3'b011: next_state = (x) ? 3'b010 : 3'b001;
            3'b100: next_state = (x) ? 3'b100 : 3'b011;
            default: next_state = 3'b000;
        endcase
    end

    // Output logic:
    // Y0 is Y[0] of the next state.
    assign Y0 = next_state[0];

    // z depends only on present state y per the table.
    always @(*) begin
        z = 1'b0;
        case (state)
            3'b011: z = 1'b1;
            3'b100: z = 1'b1;
            default: z = 1'b0;
        endcase
    end
",
    "new_content": "    // Combinational FSM based directly on present-state input y and input x.
    // Spec: outputs are derived from the table where present state is y[2:0].
    logic [2:0] next_state;

    // Next-state combinational logic from the table (present y, input x).
    always @(*) begin
        next_state = 3'b000;
        case (y)
            3'b000: next_state = (x) ? 3'b001 : 3'b000; // 000 -> 001 when x=1, stay 000 when x=0
            3'b001: next_state = (x) ? 3'b100 : 3'b001; // 001 -> 100 when x=1, stay 001 when x=0
            3'b010: next_state = (x) ? 3'b001 : 3'b010; // 010 -> 001 when x=1, stay 010 when x=0
            3'b011: next_state = (x) ? 3'b010 : 3'b001; // 011 -> 010 when x=1, ->001 when x=0
            3'b100: next_state = (x) ? 3'b100 : 3'b011; // 100 -> 100 when x=1, ->011 when x=0
            default: next_state = 3'b000;
        endcase
    end

    // Output logic:
    // Y0 is Y[0] of the next state (combinational).
    assign Y0 = next_state[0];

    // z depends only on present state y per the table.
    always @(*) begin
        z = 1'b0;
        case (y)
            3'b011: z = 1'b1; // Output z=1 for present state 011
            3'b100: z = 1'b1; // Output z=1 for present state 100
            default: z = 1'b0;
        endcase
    end
"
  }
}
